sections.css:
.liquid-shell{position: relative; background: linear-gradient(180deg,
          color-mix(in oklch, var(--card) 95%, transparent),
          color-mix(in oklch, var(--bg-soft) 88%, transparent)); border: 1px solid var(--line); box-shadow: rgba(0, 0, 0, 0.08) 0px 2px 6px, rgba(0, 0, 0, 0.35) 0px 20px 80px, rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(255, 255, 255, 0.02) 0px -1px 0px inset; backdrop-filter: blur(24px) saturate(190%);}
.hero-grid{container-type: inline-size;}
.kinetic-title{font-size: clamp(4rem, 11vw, 10rem); line-height: 0.82; letter-spacing: -0.08em; font-weight: 900; background: linear-gradient(130deg, rgb(255, 255, 255), rgba(255, 255, 255, 0.55), rgb(255, 255, 255)) 0% 0% / 220% auto text; color: transparent; animation: 7s linear 0s infinite normal none running shimmer;}
.hero-description{color: var(--muted); font-size: 1rem; line-height: 1.8; max-width: 34rem;}
.video-portal{position: absolute; top: 7%; right: -10%; width: min(60vw, 980px); height: 88%; overflow: hidden; border-radius: 4rem; transform: perspective(1800px) rotateY(-10deg) rotateX(3deg); isolation: isolate;}
.video-portal::before{content: ""; position: absolute; inset: -1px; border-radius: inherit; padding: 1px; background: linear-gradient(130deg, rgba(255, 255, 255, 0.45), rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.25)); mask: linear-gradient(rgb(0, 0, 0) 0px, rgb(0, 0, 0) 0px) content-box exclude, linear-gradient(rgb(0, 0, 0) 0px, rgb(0, 0, 0) 0px); pointer-events: none; z-index: 5;}
.video-portal video{width: 100%; height: 100%; object-fit: cover; filter: saturate(120%) contrast(112%) brightness(0.92); mask-image: radial-gradient(circle at var(--mouse-x) var(--mouse-y),
          black 25%,
          rgba(0, 0, 0, .92) 45%,
          transparent 85%);}
.video-glow{position: absolute; inset: 0px; background: radial-gradient(circle at var(--mouse-x) var(--mouse-y),
          color-mix(in oklch, var(--accent) 35%, transparent),
          transparent 55%); mix-blend-mode: screen; opacity: 0.65; pointer-events: none;}
.glass-intersection{position: absolute; left: 0px; bottom: 0px; width: 50%; height: 45%; background: linear-gradient(rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.02)); mask-image: linear-gradient(to top, black 75%, transparent 100%); border-top: 1px solid rgba(255, 255, 255, 0.08); border-right: 1px solid rgba(255, 255, 255, 0.05); pointer-events: none;}
.liquid-btn{position: relative; isolation: isolate; overflow: hidden; border-radius: 999px; padding: 1rem 1.4rem; background: linear-gradient(130deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.03)); border: 1px solid rgba(255, 255, 255, 0.1); box-shadow: rgba(255, 255, 255, 0.12) 0px 1px 0px inset, rgba(0, 0, 0, 0.24) 0px 14px 40px; transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.4s;}
.liquid-btn::before{content: ""; position: absolute; inset: -40%; background: radial-gradient(circle at var(--mouse-x) var(--mouse-y),
          rgba(255, 255, 255, .75),
          rgba(255, 255, 255, .14) 18%,
          transparent 48%); opacity: 0.9; transition: transform 0.12s linear; z-index: -1;}
.liquid-btn:hover{transform: translateY(-5px) scale(1.01); border-color: rgba(255, 255, 255, 0.25);}
.fade-edge{mask-image: linear-gradient(to right, transparent, black 10%, black 90%, transparent);}
.scroll-fade{mask-image: linear-gradient(transparent, black 12%, black 88%, transparent);}
.tiny-label{color: var(--muted); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.28em;}
h1{font-size: inherit; font-weight: inherit;}
button{font-family: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 100%; font-weight: inherit; line-height: inherit; letter-spacing: inherit; color: inherit; margin: 0px; padding: 0px;}
button{text-transform: none;}
button{appearance: button; background-color: transparent; background-image: none;}
h1, p{margin: 0px;}
button{cursor: pointer;}
video{display: block; vertical-align: middle;}
video{max-width: 100%; height: auto;}
.absolute{position: absolute;}
.relative{position: relative;}
.inset-0{inset: 0px;}
.z-10{z-index: 10;}
.z-20{z-index: 20;}
.mx-auto{margin-left: auto; margin-right: auto;}
.mt-10{margin-top: 2.5rem;}
.mt-12{margin-top: 3rem;}
.mt-2{margin-top: 0.5rem;}
.mt-20{margin-top: 5rem;}
.mt-8{margin-top: 2rem;}
.flex{display: flex;}
.h-full{height: 100%;}
.min-h-\[92vh\]{min-height: 92vh;}
.min-h-screen{min-height: 100vh;}
.w-full{width: 100%;}
.max-w-4xl{max-width: 56rem;}
.max-w-\[1600px\]{max-width: 1600px;}
.flex-col{flex-direction: column;}
.flex-wrap{flex-wrap: wrap;}
.items-center{align-items: center;}
.justify-between{justify-content: space-between;}
.gap-4{gap: 1rem;}
.gap-10{gap: 2.5rem;}
.overflow-hidden{overflow: hidden;}
.rounded-\[3rem\]{border-radius: 3rem;}
.bg-white\/5{background-color: rgba(255, 255, 255, 0.05);}
.px-8{padding-left: 2rem; padding-right: 2rem;}
.py-16{padding-top: 4rem; padding-bottom: 4rem;}
.pb-16{padding-bottom: 4rem;}
.pt-36{padding-top: 9rem;}
.text-5xl{font-size: 3rem; line-height: 1;}
.text-sm{font-size: 0.875rem; line-height: 1.25rem;}
.font-black{font-weight: 900;}
.font-semibold{font-weight: 600;}
.text-white\/45{color: rgba(255, 255, 255, 0.45);}
.opacity-\[\.04\]{opacity: 0.04;}
@media (min-width: 768px){.md\:px-16{padding-left: 4rem; padding-right: 4rem;}}

.bento{display: grid; grid-template-columns: repeat(12, 1fr); gap: 1.2rem;}
.bento-card{position: relative; overflow: hidden; border-radius: 2rem; min-height: 260px; padding: 2rem; background: linear-gradient(rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02)); border: 1px solid rgba(255, 255, 255, 0.08); backdrop-filter: blur(24px); box-shadow: rgba(255, 255, 255, 0.08) 0px 1px 0px inset, rgba(0, 0, 0, 0.2) 0px 20px 60px; transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.4s;}
.bento-card::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(400px circle at var(--mouse-x) var(--mouse-y),
          rgba(255, 255, 255, .12),
          transparent 40%); opacity: 0; transition: opacity 0.4s;}
.bento-card:hover{transform: translateY(-10px); border-color: rgba(255, 255, 255, 0.18);}
.bento-card:hover::before{opacity: 1;}
.section-reveal{opacity: 0.2; transform: translateY(80px) scale(0.96); filter: blur(18px); animation-duration: auto; animation-timing-function: linear; animation-delay: 0s; animation-iteration-count: 1; animation-direction: normal; animation-fill-mode: forwards; animation-play-state: running; animation-name: reveal; animation-timeline: view(); animation-range: entry 15% cover 40%;}
.tiny-label{color: var(--muted); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.28em;}
h2, h3{font-size: inherit; font-weight: inherit;}
h2, h3, p{margin: 0px;}
.col-span-5{grid-column: span 5 / span 5;}
.col-span-7{grid-column: span 7 / span 7;}
.mx-auto{margin-left: auto; margin-right: auto;}
.mb-16{margin-bottom: 4rem;}
.mt-6{margin-top: 1.5rem;}
.flex{display: flex;}
.max-w-\[1500px\]{max-width: 1500px;}
.max-w-lg{max-width: 32rem;}
.max-w-md{max-width: 28rem;}
.flex-wrap{flex-wrap: wrap;}
.items-end{align-items: flex-end;}
.justify-between{justify-content: space-between;}
.gap-10{gap: 2.5rem;}
.py-24{padding-top: 6rem; padding-bottom: 6rem;}
.text-4xl{font-size: 2.25rem; line-height: 2.5rem;}
.text-5xl{font-size: 3rem; line-height: 1;}
.font-black{font-weight: 900;}
.leading-8{line-height: 2rem;}
.leading-\[\.88\]{line-height: 0.88;}
.tracking-\[-0\.08em\]{letter-spacing: -0.08em;}
.tracking-tight{letter-spacing: -0.025em;}
.text-white\/50{color: rgba(255, 255, 255, 0.5);}
.text-white\/55{color: rgba(255, 255, 255, 0.55);}
@media (min-width: 768px){.md\:text-7xl{font-size: 4.5rem; line-height: 1;}}
